export const exerciseDatabase = {
    peitoral: [
        { id: 'supino_reto_barra', name: 'Supino Reto com Barra', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['tríceps', 'ombros'], gif: 'exercises/1768273343462_supindo-reto-barra.gif', description: 'Deite no banco reto com os pés apoiados no chão e as escápulas retraídas. Segure a barra com pegada pronada levemente mais larga que os ombros. Desça a barra de forma controlada até tocar levemente o peitoral médio, mantendo os cotovelos a 45–75° do corpo. Pressione de volta ao ponto inicial expirando, contraindo o peitoral no topo sem travar os cotovelos.' },
        { id: 'supino_inclinado_barra', name: 'Supino Inclinado com Barra', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['tríceps', 'ombros'], gif: 'exercises/1768273399840_Supino-inclinado-com-barra.gif', description: 'Ajuste o banco a 30–45° de inclinação e sente-se com as costas bem apoiadas. Segure a barra na largura dos ombros e desça até o peitoral superior, próximo à clavícula. Empurre de volta para cima focando na contração da porção clavicular do peitoral grande. Mantenha os cotovelos a 75° do tronco e as escápulas sempre retraídas.' },
        { id: 'supino_declinado_barra', name: 'Supino Declinado com Barra', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['tríceps'], gif: 'exercises/1768273381081_supino-declinado-barra.gif', description: 'Deite no banco declinado (15–30°) com os pés presos nos suportes. Segure a barra com pegada pronada na largura dos ombros. Desça controladamente até o peitoral inferior (linha do esterno) e pressione de volta. Esse ângulo prioriza a porção esterno-costal do peitoral maior, dando definição à parte baixa do peito.' },
        { id: 'supino_halteres', name: 'Supino com Halteres', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['tríceps', 'ombros'], gif: 'exercises/1768273360693_Supino-com-halteres-com-pegada-fechada.gif', description: 'Deite no banco com um halter em cada mão na altura do peitoral, cotovelos a 75° do tronco. Os halteres permitem maior amplitude de movimento que a barra, proporcionando melhor pré-estiramento e ativação muscular. Pressione para cima e levemente para o centro, aproximando os halteres sem bater. Controle a descida em 2–3 segundos.' },
        { id: 'supino_inclinado_halteres', name: 'Supino Inclinado com Halteres', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['tríceps', 'ombros'], gif: 'exercises/1768273403983_Supino-inclinado-com-halteres-e-pegada-fechada.gif', description: 'No banco inclinado a 30–45°, posicione os halteres na altura do peitoral superior com os cotovelos abertos. Desça os halteres em arco controlado até sentir bom estiramento. Pressione de volta para cima e levemente para o centro ao final. A inclinação direciona a tensão para a porção clavicular do peitoral, que muitas vezes é subdesenvolvida.' },
        { id: 'supino_maquina', name: 'Supino na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'peitoral', secondaryMuscles: ['tríceps'], gif: 'exercises/1768273421082_Supino-na-Máquina-para-Miolo-do-Peitoral.gif', description: 'Ajuste o banco para que as alças fiquem alinhadas ao peitoral médio quando sentado. Empurre as alças para frente de forma controlada, estendendo os braços sem travar os cotovelos. Retorne lentamente sentindo o estiramento no peitoral. Elimina a necessidade de estabilização, ideal para iniciantes focarem na contração e para cargas elevadas em segurança.' },
        { id: 'supino_smith', name: 'Supino no Smith', equipment: 'smith', difficulty: 'iniciante', primaryMuscle: 'peitoral', secondaryMuscles: ['tríceps', 'ombros'], gif: 'exercises/1768273423085_Supino-na-máquina-Smith.gif', description: 'Posicione o banco reto sob a barra do Smith e deite com a barra alinhada ao peitoral médio. O trilho guiado elimina o trabalho dos estabilizadores, permitindo foco total na contração e cargas elevadas. Desça controladamente, toque levemente o peitoral e pressione de volta. Útil para treinar sem parceiro e para iniciantes aprenderem o padrão de movimento.' },
        { id: 'crucifixo_halteres', name: 'Crucifixo com Halteres', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['ombros'], gif: 'exercises/1768273301871_Crucifixo-com-Halteres-Declinado.gif', description: 'Deite no banco com os halteres acima do peitoral, palmas voltadas uma para a outra e cotovelos levemente flexionados. Abra os braços lateralmente em arco amplo até sentir estiramento profundo no peitoral. Retorne como se estivesse abraçando um barril, mantendo o ângulo do cotovelo constante. Exercício de isolamento por excelência para maximizar a amplitude do peitoral.' },
        { id: 'crucifixo_inclinado', name: 'Crucifixo Inclinado', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['ombros'], gif: 'exercises/1768273303423_Crucifixo-com-Halteres-Inclinado.gif', description: 'No banco inclinado a 30–45°, realize o mesmo movimento do crucifixo convencional. O ângulo de inclinação direciona a tensão para a porção clavicular (superior) do peitoral, que é frequentemente subdesenvolvida. Abra amplamente os braços para máximo estiramento e feche em arco contraindo o peitoral superior. Essencial para volume e separação na parte de cima do peito.' },
        { id: 'cross_polia_alta', name: 'Cross Over Polia Alta', equipment: 'cabo', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['ombros'], gif: 'exercises/1768273286286_Cross-over-polia-Alta.gif', description: 'De pé no centro do cross over com as polias na posição mais alta, segure as alças e incline levemente o tronco para frente. Puxe os cabos em arco para baixo e para frente, encontrando as mãos à altura do umbigo. Mantenha os cotovelos levemente flexionados durante todo o movimento. Contraia o peitoral intensamente no ponto de cruzamento e retorne lentamente controlando a resistência.' },
        { id: 'cross_polia_baixa', name: 'Cross Over Polia Baixa', equipment: 'cabo', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['ombros'], gif: 'exercises/1768273288779_Cross-over-polia-baixa.gif', description: 'Com as polias na posição mais baixa, puxe os cabos para cima e para a frente em arco, encontrando as mãos na altura do peitoral superior. O ângulo ascendente ativa principalmente a porção clavicular do peitoral maior. Mantenha os cotovelos levemente flexionados e o tronco estável. Ideal para completar o estímulo no peito superior após exercícios com barra ou halteres.' },
        { id: 'voador_maquina', name: 'Voador na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'peitoral', secondaryMuscles: ['ombros'], gif: 'exercises/1768273448833_Voador-na-Máquina.gif', description: 'Ajuste o assento para que os cotovelos fiquem alinhados ao peitoral médio quando apoiados nas almofadas. Pressione os braços para a frente em arco semicircular, contraindo o peitoral no ponto de encontro. Retorne lentamente sentindo o estiramento na abertura máxima. A máquina mantém resistência constante ao longo do arco, perfeita para pump muscular e finalização do treino de peito.' },
        { id: 'crucifixo_maquina', name: 'Crucifixo Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'peitoral', secondaryMuscles: ['ombros'], gif: 'exercises/1768273313041_Crucifixo-Maquina.gif', description: 'Sente-se na máquina pec deck com as costas bem apoiadas e as alças na altura do peitoral. Empurre as alças para a frente até se encontrarem, contraindo o peitoral isometricamente por 1–2 segundos. Retorne de forma controlada. A resistência guiada permite foco total na ativação muscular sem preocupação com equilíbrio, ideal para iniciantes e para altas repetições.' },
        { id: 'paralelas', name: 'Paralelas (Peito)', equipment: 'corpo', difficulty: 'avancado', primaryMuscle: 'peitoral', secondaryMuscles: ['tríceps', 'ombros'], gif: 'exercises/1768273335731_Paralelas.gif', description: 'Apoie-se nas paralelas e incline o tronco para frente entre 20–30° para transferir o foco do tríceps para o peitoral. Desça controladamente até os cotovelos atingirem 90°, sentindo o estiramento no peitoral. Pressione de volta sem travar completamente os cotovelos. Quanto maior a inclinação do tronco, maior o recrutamento do peitoral inferior. Adicione peso com cinto para progressão.' },
        { id: 'pullover_halter', name: 'Pullover com Haltere', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'peitoral', secondaryMuscles: ['costas', 'tríceps'], gif: 'exercises/1768273339330_Pullover-com-haltere.gif', description: 'Deite transversalmente no banco com apenas as costas apoiadas e os pés no chão. Segure um halter com as duas mãos acima do peito e leve-o para trás da cabeça em arco, mantendo os cotovelos levemente flexionados. O peitoral e o grande dorsal trabalham juntos nessa amplitude única. Retorne contraindo o peitoral e o dorsal simultaneamente. Excelente para expansão torácica e flexibilidade de ombros.' },
        { id: 'flexao_frente', name: 'Flexão de Frente', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'peitoral', secondaryMuscles: ['tríceps', 'ombros'], gif: 'exercises/1768273284843_Apoio-de-frente-de-joelhos.gif', description: 'Na posição de prancha com as mãos um pouco além da largura dos ombros, dobre os cotovelos para baixar o peito próximo ao chão. Mantenha o corpo rígido com o core contraído e os quadris alinhados. Empurre de volta contraindo o peitoral. Pode ser feito de joelhos para reduzir dificuldade. Um dos exercícios mais completos para peito, tríceps e ombros sem equipamento.' },
    ],

    costas: [
        { id: 'puxada_frente', name: 'Puxada Frontal', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272794811_Puxada-Alta-com-Alavanca.gif', description: 'Sentado na máquina de puxada com os joelhos fixos sob o suporte, segure a barra com pegada pronada larga. Incline levemente o tronco para trás e puxe a barra em direção ao peitoral superior, conduzindo os cotovelos para baixo e para trás. Contraia o grande dorsal no ponto final, segurando por 1 segundo. Estenda os braços completamente na volta para alongar as costas.' },
        { id: 'puxada_triangulo', name: 'Puxada com Triângulo', equipment: 'maquina', difficulty: 'intermediario', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272796062_Puxada-Alta-com-Triângulo.gif', description: 'Na puxada alta com o triângulo (pegada neutra e estreita), puxe o acessório até o peitoral inferior mantendo o tronco ligeiramente reclinado. A pegada neutra permite maior recrutamento do grande dorsal médio e romboides, além de ser mais confortável para os pulsos. Contraia as escápulas no ponto final e estenda completamente os braços na subida.' },
        { id: 'puxada_nuca', name: 'Puxada Alta Nuca', equipment: 'maquina', difficulty: 'intermediario', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272804924_Puxada-alta-na-polia-nuca.gif', description: 'Com pegada pronada larga, incline a cabeça levemente para frente e puxe a barra para trás até a nuca. Exige boa mobilidade de ombros e deve ser executado com cuidado. A variante nuca ativa o grande dorsal lateral de forma diferenciada. Recomendado apenas para atletas experientes com mobilidade adequada. Evite se sentir desconforto nos ombros ou pescoço.' },
        { id: 'remada_baixa', name: 'Remada Sentada com Cabo', equipment: 'cabo', difficulty: 'iniciante', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272886260_Remada-Sentada-com-Cabo.gif', description: 'Sentado no banco com os pés apoiados na plataforma e os joelhos levemente flexionados, segure o cabo com o triângulo ou barra. Mantenha o tronco ereto e puxe o cabo até o abdômen, retraindo completamente as escápulas no ponto final. Segure por 1–2 segundos contraindo o grande dorsal e romboides. Estenda os braços controladamente para o alongamento total.' },
        { id: 'remada_curvada', name: 'Remada Curvada com Barra', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'costas', secondaryMuscles: ['bíceps', 'lombar'], gif: 'exercises/1768272847536_Remada-curvada-com-barra-de-pegada-alternada-ampla-com-adução-de-escapula.gif', description: 'Com os pés na largura dos ombros, incline o tronco a 45° mantendo a lombar neutra e o core contraído. Segure a barra com pegada pronada ou supinada na largura dos ombros. Puxe a barra até o umbigo, levando os cotovelos para trás e retraindo as escápulas. Um dos melhores exercícios compostos para espessura de costas, ativando grande dorsal, romboides e bíceps.' },
        { id: 'remada_unilateral', name: 'Remada Serrote', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272893531_remada-serrote.gif', description: 'Apoie um joelho e a mão ipsilateral no banco formando um ângulo de 90° com o tronco paralelo ao chão. Com o halter pendendo do braço livre, puxe-o até o quadril conduzindo o cotovelo para cima e para trás. Retraia a escápula no topo e estenda completamente o braço na descida para máximo estiramento. Unilateral, corrige assimetrias e permite maior amplitude de movimento.' },
        { id: 'remada_maquina', name: 'Remada na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272890092_Remada-Sentada-na-Máquina.gif', description: 'Ajuste o assento para que o peito fique bem apoiado no suporte frontal. Segure as alças e puxe em direção ao abdômen, retraindo as escápulas e levando os cotovelos para trás. O apoio no peito elimina a compensação do tronco, garantindo isolamento das costas. Excelente para iniciantes aprenderem o padrão motor da remada com segurança e para trabalho de alto volume.' },
        { id: 'remada_cavalinho', name: 'Remada Cavalinho', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272894847_Remada-T-com-alavanca.gif', description: 'Na alavanca T com o peito apoiado no suporte, segure as alças e puxe bilateralmente até o peitoral. O apoio frontal estabiliza o tronco, eliminando compensações e permitindo foco total nas costas. Retraia as escápulas no topo e estenda completamente na descida. Eficaz para espessura do grande dorsal, romboides e trapézio médio com movimento estabilizado.' },
        { id: 'pulldown_corda', name: 'Pulldown com Corda', equipment: 'cabo', difficulty: 'intermediario', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272770950_Pulldown-com-corda.gif', description: 'Na polia alta com a corda, posicione-se ajoelhado ou em pé. Puxe a corda para baixo, separando levemente as pontas ao final do movimento para aumentar a contração do grande dorsal. Mantenha os cotovelos apontando para baixo e para trás. A corda permite rotação natural dos punhos, tornando o movimento mais confortável e aumentando a contração final do dorsal.' },
        { id: 'barra_fixa', name: 'Barra Fixa', equipment: 'corpo', difficulty: 'avancado', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272451160_Puxada-escapular-na-barra-fixa.gif', description: 'Pendurado na barra com pegada pronada larga, ative as escápulas puxando-as para baixo antes de iniciar o movimento. Puxe o corpo até o queixo ultrapassar a barra, contraindo grande dorsal e bíceps. Desça de forma controlada até a extensão quase completa. Um dos exercícios mais efetivos para largura de costas. A força relativa ao peso corporal determina a dificuldade.' },
        { id: 'barra_fixa_assistida', name: 'Barra Fixa Assistida', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272740981_Barra-Fixa-Assistida.gif', description: 'No gravitron, posicione os joelhos ou os pés na plataforma de assistência e selecione um contrapeso que permita executar 8–12 repetições com boa técnica. Puxe o corpo até o queixo ultrapassar a barra, retraindo as escápulas. O contrapeso reduz o peso efetivo, permitindo desenvolver a força necessária para a barra fixa sem assistência. Reduza gradualmente o contrapeso ao progredir.' },
        { id: 'levantamento_terra', name: 'Levantamento Terra', equipment: 'barra', difficulty: 'avancado', primaryMuscle: 'costas', secondaryMuscles: ['glúteos', 'pernas'], gif: 'exercises/1768272761874_levantamento-terra-no-smith.gif', description: 'Com os pés na largura dos quadris e a barra sobre o meio do pé, segure com pegada pronada ou mista. Desça os quadris, eleve o peito e puxe a omoplata para trás antes de iniciar. Empurre o chão para baixo e erga a barra mantendo-a rente às pernas durante todo o movimento. Um dos exercícios mais completos da musculação, ativando toda a cadeia posterior: eretores, glúteos, isquiotibiais e trapézio.' },
        { id: 'pullover_polia', name: 'Pullover na Polia', equipment: 'cabo', difficulty: 'intermediario', primaryMuscle: 'costas', secondaryMuscles: ['tríceps'], gif: 'exercises/1768272788043_Pullover-com-cabo-sentado.gif', description: 'De pé ou sentado, segure a alça da polia alta com os braços estendidos acima da cabeça. Mantendo os cotovelos levemente flexionados, puxe o cabo em arco para baixo até a altura dos quadris. O grande dorsal é o principal motor do movimento. Ideal para desenvolver o formato em V das costas e para iniciantes que ainda não conseguem fazer barra fixa.' },
        { id: 'remada_inclinada', name: 'Remada Inclinada com Halteres', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'costas', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272839399_remada-com-banco-inclinado-com-haltres.gif', description: 'Ajuste o banco a 45° e deite de bruços com um halter em cada mão. Puxe os halteres para cima e para os lados, retraindo as escápulas no ponto mais alto. O apoio no banco elimina completamente a compensação do tronco, isolando as costas. Excelente para iniciantes aprenderem o padrão motor da remada e para treino intenso de costas sem sobrecarga lombar.' },
    ],

    ombros: [
        { id: 'desenvolvimento_halteres', name: 'Desenvolvimento com Halteres', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'ombros', secondaryMuscles: ['tríceps'], gif: 'exercises/1768273076771_Desenvolvimento-com-Halteres.gif', description: 'Sentado no banco com as costas apoiadas ou em pé com core firme, segure os halteres na altura dos ombros com cotovelos a 90°. Pressione os halteres para cima até quase a extensão completa sem bloquear os cotovelos. Desça de forma controlada até os cotovelos voltarem a 90°. Trabalha os três feixes do deltoides com ênfase no anterior e médio, além do tríceps como motor secundário.' },
        { id: 'desenvolvimento_maquina', name: 'Desenvolvimento na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'ombros', secondaryMuscles: ['tríceps'], gif: 'exercises/1768273097703_Desenvolvimento-de-ombro-na-maquina.gif', description: 'Ajuste o assento para que as alças fiquem alinhadas à altura dos ombros. Empurre as alças para cima em linha reta até a quase extensão e desça controladamente até sentir o estiramento nos deltoides. O guia da máquina elimina o trabalho de estabilização, permitindo foco na contração e uso de cargas maiores. Excelente para volume e para aprender o padrão do desenvolvimento.' },
        { id: 'desenvolvimento_arnold', name: 'Desenvolvimento Arnold', equipment: 'halteres', difficulty: 'avancado', primaryMuscle: 'ombros', secondaryMuscles: ['tríceps'], gif: 'exercises/1768273065140_Desenvolvimento-arnold-com-um-braco.gif', description: 'Comece com os halteres à frente do rosto na altura do queixo, palmas voltadas para você. Ao empurrar os halteres para cima, gire os punhos até as palmas ficarem voltadas para frente no topo. Inverta a rotação na descida. Esse movimento rotacional, criado por Arnold Schwarzenegger, ativa os três feixes do deltoides de forma mais completa que o desenvolvimento convencional.' },
        { id: 'desenvolvimento_barra', name: 'Desenvolvimento com Barra', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'ombros', secondaryMuscles: ['tríceps'], gif: 'exercises/1768273074762_Desenvolvimento-com-Barra-sentado.gif', description: 'Sentado ou em pé, segure a barra com pegada pronada na largura dos ombros. Pressione a barra para cima à frente da cabeça até a quase extensão. Desça controladamente até a barra atingir a altura do pescoço. Permite cargas maiores que os halteres, ideal para ganho de força. Mantenha o core contraído para proteger a lombar, especialmente na versão em pé.' },
        { id: 'elevacao_lateral', name: 'Elevação Lateral', equipment: 'halteres', difficulty: 'iniciante', primaryMuscle: 'ombros', secondaryMuscles: [], gif: 'exercises/1768273189810_elevacao-letaral-com-haltrers.gif', description: 'De pé com os halteres ao lado do corpo e uma leve flexão nos cotovelos, eleve os braços lateralmente até a altura dos ombros. Incline levemente o polegar para baixo (como se estivesse derramando água) para maximizar a ativação do deltoides médio. Evite usar impulso do corpo e controle a descida em 2–3 segundos. O principal exercício de isolamento para a largura dos ombros.' },
        { id: 'elevacao_lateral_maquina', name: 'Elevação Lateral Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'ombros', secondaryMuscles: [], gif: 'exercises/1768273182145_Elevacao-lateral-na-maquina.gif', description: 'Sente-se na máquina e posicione os cotovelos nas almofadas laterais alinhadas aos ombros. Eleve os braços contra a resistência até a altura dos ombros. A máquina mantém tensão constante durante todo o arco, incluindo na parte inferior onde os halteres perdem tensão. Excelente para séries de alto volume com técnica consistente e sem compensações.' },
        { id: 'elevacao_frontal', name: 'Elevação Frontal', equipment: 'halteres', difficulty: 'iniciante', primaryMuscle: 'ombros', secondaryMuscles: [], gif: 'exercises/1768273155110_elevacao-frontal-com-halteres.gif', description: 'De pé com os halteres à frente das coxas e palmas voltadas para baixo, eleve um ou ambos os halteres à frente até a altura dos ombros. Mantenha os cotovelos levemente flexionados e o tronco estático, sem usar impulso. O movimento em flexão do ombro foca no deltoides anterior. Pode ser feito alternado para melhor controle ou simultâneo para maior intensidade.' },
        { id: 'elevacao_frontal_barra', name: 'Elevação Frontal com Barra', equipment: 'barra', difficulty: 'iniciante', primaryMuscle: 'ombros', secondaryMuscles: [], gif: 'exercises/1768273146563_Elevacao-Frontal-com-Barra.gif', description: 'Em pé com a barra segura com pegada pronada na largura dos ombros, eleve a barra à frente até a altura dos ombros ou levemente acima. Mantenha os cotovelos levemente flexionados e evite balançar o tronco. A barra permite trabalhar ambos os ombros simultaneamente com carga consistente. Foco no deltoides anterior, importante para o desenvolvimento equilibrado dos ombros.' },
        { id: 'remada_alta', name: 'Remada Alta', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'ombros', secondaryMuscles: ['trapézio'], gif: 'exercises/1768272700951_Afundo-Caminhando.gif', description: 'Em pé com a barra segura com pegada pronada estreita (mãos a 20–30 cm), puxe a barra verticalmente até a altura do queixo, conduzindo os cotovelos para fora e para cima acima dos punhos. Ativa o deltoides médio e o trapézio superior. Evite pegada muito fechada que pode causar impingimento subacromial. Controle a descida. Complementa bem o desenvolvimento para ombros completos.' },
        { id: 'crucifixo_inverso', name: 'Crucifixo Inverso', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'ombros', secondaryMuscles: ['costas'], gif: 'exercises/1768273055626_Crucifixo-Invertido-com-Halteres.gif', description: 'Incline o tronco para frente a 45–90° com os halteres pendendo abaixo. Com os cotovelos levemente flexionados, abra os braços lateralmente e para cima em arco, retraindo as escápulas no ponto mais alto. Ativa principalmente o deltoides posterior e os romboides. Fundamental para equilibrar os ombros e melhorar a postura. Evite usar impulso do tronco.' },
        { id: 'voador_inverso', name: 'Voador Invertido', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'ombros', secondaryMuscles: ['costas'], gif: 'exercises/1768272912810_voador-invertido.gif', description: 'Sente-se de costas para a máquina pec deck e ajuste as alças para a altura dos ombros. Puxe as alças para trás em arco, retraindo as escápulas e contraindo o deltoides posterior no ponto final. Retorne de forma controlada. Isola o deltoides posterior com eficiência, músculo frequentemente negligenciado e essencial para saúde dos ombros e postura equilibrada.' },
        { id: 'elevacao_lateral_cabo', name: 'Elevação Lateral com Cabo', equipment: 'cabo', difficulty: 'intermediario', primaryMuscle: 'ombros', secondaryMuscles: [], gif: 'exercises/1768273196367_elevacao-unilateral-no-cross.gif', description: 'Posicione a polia na posição mais baixa e segure a alça com a mão oposta ao lado da máquina. Eleve o braço lateralmente até a altura do ombro, com o cotovelo levemente flexionado. O cabo mantém tensão constante em toda a amplitude, especialmente na fase inferior onde os halteres têm pouca resistência. Unilateral, permite corrigir desequilíbrios e focar em cada deltoides médio individualmente.' },
    ],

    biceps: [
        { id: 'rosca_direta', name: 'Rosca Direta com Barra', equipment: 'barra', difficulty: 'iniciante', primaryMuscle: 'bíceps', secondaryMuscles: ['antebraço'], gif: 'exercises/1768272636144_Rosca-Direta-com-Barra-deitado-em-Banco-Alto.gif', description: 'Em pé ou sentado com a barra segura com pegada supinada na largura dos ombros, mantenha os cotovelos fixos ao lado do tronco. Flexione os braços trazendo a barra até os ombros, contraindo o bíceps no topo. Desça de forma controlada até a extensão quase completa. O exercício mais clássico para bíceps, fundamental para ganho de massa. Não balance o tronco para não perder o isolamento.' },
        { id: 'rosca_barra_w', name: 'Rosca com Barra W', equipment: 'barra', difficulty: 'iniciante', primaryMuscle: 'bíceps', secondaryMuscles: ['antebraço'], gif: 'exercises/1768272633674_rosca-direta-barra-W-sentado-banco.gif', description: 'Semelhante à rosca direta, mas com a barra EZ (W) que posiciona os punhos em semipronação, reduzindo a tensão nos pulsos e cotovelos. A pegada é mais ergonômica e confortável para muitas pessoas. Mantenha os cotovelos fixos e flexione completamente até sentir a contração máxima do bíceps. Ideal para sessões de alto volume sem desconforto articular.' },
        { id: 'rosca_halteres', name: 'Rosca com Halteres', equipment: 'halteres', difficulty: 'iniciante', primaryMuscle: 'bíceps', secondaryMuscles: ['antebraço'], gif: 'exercises/1768272607058_Rosca-com-halteres-no-colete-scott.gif', description: 'Em pé ou sentado com os halteres ao lado do corpo, flexione um braço de cada vez (alternado) ou ambos simultaneamente. Durante o movimento, gire o punho de neutro para supinado (palma para cima) para maximizar a contração do bíceps. Essa supinação ativa a cabeça curta do bíceps com mais eficiência. Permite identificar e corrigir desequilíbrios entre os lados.' },
        { id: 'rosca_martelo', name: 'Rosca Martelo', equipment: 'halteres', difficulty: 'iniciante', primaryMuscle: 'bíceps', secondaryMuscles: ['antebraço'], gif: 'exercises/1768272657628_Rosca-martelo-com-corda.gif', description: 'Com os halteres em pegada neutra (palmas voltadas para o corpo como se segurasse um martelo), flexione os braços sem rotar os punhos. Ativa prioritariamente o braquiorradial e o braquial anterior, que adicionam espessura e plenitude ao braço. Pode ser feito alternado ou simultâneo. Com a corda no cabo mantém tensão constante ao longo de todo o movimento.' },
        { id: 'rosca_concentrada', name: 'Rosca Concentrada', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'bíceps', secondaryMuscles: [], gif: 'exercises/1768272611191_Rosca-Concentrada-2.gif', description: 'Sentado num banco com os pés afastados, apoie o cotovelo na face interna da coxa. Segure o halter com pegada supinada e flexione o braço até a contração máxima, supinando completamente o punho no final. Máximo isolamento do bíceps sem possibilidade de trapaça com o tronco. Excelente para trabalhar o pico do bíceps e a simetria entre os lados.' },
        { id: 'rosca_scott', name: 'Rosca Scott', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'bíceps', secondaryMuscles: [], gif: 'exercises/1768272675771_rosca-no-scort.gif', description: 'No banco Scott, posicione as partes posteriores dos braços (tríceps) firmes contra a superfície inclinada. Segure a barra com pegada supinada e flexione os braços. O banco elimina qualquer possibilidade de usar impulso do tronco e estica o bíceps na posição estendida, aumentando o recrutamento. Ótimo para a cabeça longa do bíceps e espessura geral do músculo.' },
        { id: 'rosca_scott_haltere', name: 'Rosca Scott com Haltere', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'bíceps', secondaryMuscles: [], gif: 'exercises/1768272684305_Rosca-Scott-com-Halteres-Martelo-no-Banco.gif', description: 'Versão unilateral da rosca Scott. Apoie um braço no banco Scott e realize a rosca com o halter, supinando completamente o punho no topo da flexão. Trabalha um braço por vez, permitindo máxima concentração no bíceps e correção de assimetrias. A supinação ativa a porção curta do bíceps com mais intensidade que a barra EZ.' },
        { id: 'rosca_banco_inclinado', name: 'Rosca Banco Inclinado', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'bíceps', secondaryMuscles: [], gif: 'exercises/1768272579600_Rosca-Banco-Inclinado.gif', description: 'Deite num banco inclinado a 45–60° com os halteres pendendo com os braços estendidos atrás da linha do tronco. Flexione os braços sem mover os ombros para frente. O ângulo inclinado alonga a cabeça longa do bíceps além do habitual, aumentando o pré-estiramento e o recrutamento muscular. Excelente para pico e alongamento máximo do bíceps.' },
        { id: 'rosca_polia', name: 'Rosca no Cabo', equipment: 'cabo', difficulty: 'iniciante', primaryMuscle: 'bíceps', secondaryMuscles: [], gif: 'exercises/1768272673310_Rosca-no-Cabo-Deitado.png', description: 'Na polia baixa com barra ou alças, realize a rosca em pé mantendo os cotovelos fixos ao lado do corpo. O cabo mantém tensão constante ao longo de todo o arco, incluindo no ponto de maior contração (o que não acontece com barra ou halteres que perdem tensão no topo). Ótimo para finalizar o treino de bíceps com sensação de pump intenso.' },
        { id: 'rosca_polia_alta', name: 'Rosca Polia Alta', equipment: 'cabo', difficulty: 'intermediario', primaryMuscle: 'bíceps', secondaryMuscles: [], gif: 'exercises/1768272563322_biceps-polia-alta-dupla.gif', description: 'Com as polias na posição mais alta em ambos os lados, posicione-se no centro em posição de crucifixo. Flexione os cotovelos puxando os cabos em direção à cabeça, como um double biceps pose. Esta posição de rotação externa do ombro recruta o bíceps de forma única e espetacular, dando forma ao pico. Mova apenas os antebraços, sem mover os braços superiores.' },
        { id: 'rosca_maquina', name: 'Rosca na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'bíceps', secondaryMuscles: [], gif: 'exercises/1768272567833_Máquina-de-rosca-direta.gif', description: 'Sente-se na máquina e posicione os cotovelos nas almofadas alinhadas ao eixo de rotação. Flexione os braços contra a resistência guiada até a contração máxima. A máquina elimina a necessidade de estabilização e garante o padrão correto de movimento. Ideal para iniciantes, para séries até a falha com segurança e para o final do treino quando a fadiga já é alta.' },
    ],

    triceps: [
        { id: 'triceps_corda', name: 'Tríceps Pulley Corda', equipment: 'cabo', difficulty: 'iniciante', primaryMuscle: 'tríceps', secondaryMuscles: [], gif: 'exercises/1768273832007_Tríceps-pulley-corda.gif', description: 'Na polia alta com a corda, posicione-se com o tronco levemente inclinado para frente e os cotovelos fixos ao lado do tronco. Puxe a corda para baixo estendendo os cotovelos e, no ponto final, separe as pontas da corda para os lados para maximizar a contração da cabeça lateral do tríceps. Retorne lentamente controlando a resistência. O exercício mais popular para definição e pump do tríceps.' },
        { id: 'triceps_barra', name: 'Tríceps Pulley Barra', equipment: 'cabo', difficulty: 'iniciante', primaryMuscle: 'tríceps', secondaryMuscles: [], gif: 'exercises/1768273827821_Tríceps-Pulley-barra-V.gif', description: 'Na polia alta com barra reta, fique de pé com o tronco levemente inclinado e os cotovelos fixos ao lado do tronco. Empurre a barra para baixo até a extensão completa dos cotovelos, contraindo o tríceps intensamente. Retorne controladamente sem deixar os cotovelos subirem acima da linha do peito. Permite carga maior que a corda, ótimo para ganho de volume no tríceps.' },
        { id: 'triceps_barra_v', name: 'Tríceps Pulley Barra V', equipment: 'cabo', difficulty: 'iniciante', primaryMuscle: 'tríceps', secondaryMuscles: [], gif: 'exercises/1768273827821_Tríceps-Pulley-barra-V.gif', description: 'Com a barra V (EZ invertida) na polia alta, a pegada semipronada é mais ergonômica e reduz a tensão nos pulsos comparado à barra reta. Mantenha os cotovelos fixos ao lado do tronco e empurre para baixo até a extensão completa. A barra V distribui melhor a carga entre as três cabeças do tríceps. Ideal para quem sente desconforto nos punhos com a barra reta.' },
        { id: 'triceps_frances', name: 'Tríceps Francês com Halter', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'tríceps', secondaryMuscles: [], gif: 'exercises/1768273813636_Tríceps-Frances-com-Halteres.gif', description: 'Sentado ou deitado, segure um halter com as duas mãos acima da cabeça com os braços estendidos. Mantendo os cotovelos apontados para frente e próximos à cabeça, dobre-os para baixar o halter atrás da cabeça. Estenda de volta à posição inicial. Ativa especialmente a cabeça longa do tríceps (maior das três), que só é ativada completamente com o braço acima da cabeça.' },
        { id: 'triceps_frances_barra', name: 'Tríceps Francês com Barra', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'tríceps', secondaryMuscles: [], gif: 'exercises/1768273777725_Triceps-frances-barra-W.gif', description: 'Sentado ou em pé, segure a barra W acima da cabeça com pegada pronada. Mantendo os cotovelos voltados para frente e próximos à cabeça, dobre-os abaixando a barra atrás da cabeça. Estenda os braços de volta ao topo. A barra W reduz a tensão nos punhos nessa posição. Potente para volume da cabeça longa do tríceps. Mantenha o core contraído para proteger a lombar.' },
        { id: 'triceps_testa', name: 'Tríceps Testa com Barra', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'tríceps', secondaryMuscles: [], gif: 'exercises/1768273836416_Tríceps-Testa-com-Barra-Pegada-Invertida.gif', description: 'Deitado no banco com a barra segura com pegada pronada estreita acima do peito, dobre os cotovelos levando a barra em direção à testa ou levemente além da cabeça. Estenda os braços de volta. Os cotovelos ficam com abertura média (45° do tronco). Trabalha principalmente as cabeças medial e lateral do tríceps. A barra W é mais confortável que a reta para este exercício.' },
        { id: 'triceps_testa_haltere', name: 'Tríceps Testa com Halteres', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'tríceps', secondaryMuscles: [], gif: 'exercises/1768273796344_Triceps-testa-com-halteres.gif', description: 'Deitado no banco com um halter em cada mão acima do peito, dobre os cotovelos abaixando os halteres ao lado das orelhas. Estenda os braços de volta. Os halteres permitem rotação natural dos punhos e maior amplitude de movimento comparado à barra. Pode ser feito unilateral para correção de assimetrias. Eficaz para as cabeças medial e lateral do tríceps.' },
        { id: 'triceps_coice', name: 'Tríceps Coice', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'tríceps', secondaryMuscles: [], gif: 'exercises/1768273809073_Tríceps-Coice-com-Halteres.gif', description: 'Incline o tronco para frente a 45° apoiando uma mão no banco. Mantenha o braço com o halter dobrado a 90°, com o cotovelo elevado e alinhado ao tronco. Estenda o braço para trás até a extensão completa, contraindo o tríceps intensamente. Retorne controladamente. O exercício proporciona excelente contração na posição final e isola bem o tríceps. Pode ser feito bilateral ou unilateral.' },
        { id: 'triceps_banco', name: 'Tríceps no Banco', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'tríceps', secondaryMuscles: ['ombros'], gif: 'exercises/1768273823473_Tríceps-no-Banco.gif', description: 'Apoie as palmas das mãos no banco atrás do corpo com os dedos voltados para frente. Com as pernas estendidas (ou flexionadas para facilitar), dobre os cotovelos para baixar o corpo próximo ao chão. Empurre de volta até quase a extensão completa. Mantenha o corpo próximo ao banco durante todo o movimento. Adicione peso no colo para aumentar a intensidade progressivamente.' },
        { id: 'supino_fechado', name: 'Supino Pegada Fechada', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'tríceps', secondaryMuscles: ['peitoral'], gif: 'exercises/1768273444074_Supino.gif', description: 'No banco reto, segure a barra com pegada pronada estreita (mãos a 20–30 cm de distância). Desça a barra até o peitoral mantendo os cotovelos próximos ao tronco e empurre de volta. O espaçamento reduzido na pegada transfere o trabalho do peitoral para o tríceps. Exercício composto que permite grandes cargas e é excelente para ganho de força e massa nos três feixes do tríceps.' },
        { id: 'mergulho_triceps', name: 'Mergulho de Tríceps', equipment: 'corpo', difficulty: 'avancado', primaryMuscle: 'tríceps', secondaryMuscles: ['peitoral'], gif: 'exercises/1768273755948_Mergulho-de-tríceps-com-alavanca.gif', description: 'Apoiado nas paralelas com o tronco ereto (vertical), dobre os cotovelos para baixar o corpo controladamente. Empurre de volta sem travar os cotovelos no topo. Manter o tronco ereto concentra a tensão no tríceps; inclinar para frente ativa mais o peitoral. Um dos exercícios mais efetivos para o tríceps. Para progressão, adicione peso com cinto ou segurando um halter entre os pés.' },
        { id: 'triceps_maquina', name: 'Tríceps na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'tríceps', secondaryMuscles: [], gif: 'exercises/1768273737400_Extensao-de-tríceps-na-máquina.gif', description: 'Sentado na máquina de extensão de tríceps, posicione os cotovelos nas almofadas alinhadas ao eixo de rotação. Pressione as alças para baixo estendendo os cotovelos até a posição final, contraindo o tríceps. Retorne controladamente. O movimento guiado garante segurança e técnica consistente. Ideal para iniciantes aprenderem o padrão ou para séries de alto volume ao final do treino.' },
    ],

    pernas: [
        { id: 'agachamento_livre', name: 'Agachamento Livre', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos', 'lombar'], gif: 'exercises/1768272932666_Agachamento-na-Maquina-Abdutora.gif', description: 'Com a barra apoiada nos trapézios (posição alta) ou nos deltoides posteriores (posição baixa), afaste os pés na largura dos ombros com as pontas levemente voltadas para fora. Desça os quadris para trás e para baixo mantendo o tronco ereto e os joelhos alinhados com os pés. Desça até as coxas ficarem paralelas ao chão ou abaixo. Suba empurrando o chão, contraindo glúteos e quadríceps.' },
        { id: 'agachamento_smith', name: 'Agachamento no Smith', equipment: 'smith', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos'], gif: 'exercises/1768273509148_Agachamento-no-Smith.gif', description: 'Posicione-se sob a barra do Smith com os pés levemente à frente do eixo vertical da barra. Agache controladamente até as coxas ficarem paralelas ao chão. O trilho guiado estabiliza a barra, permitindo foco no movimento das pernas sem preocupação com equilíbrio. Ideal para iniciantes aprenderem a mecânica do agachamento e para treinamentos com carga elevada em segurança.' },
        { id: 'agachamento_hack', name: 'Agachamento Hack', equipment: 'maquina', difficulty: 'intermediario', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos'], gif: 'exercises/1768273503775_Agachamento-na-Máquina-Hack.gif', description: 'Na máquina Hack, posicione os ombros sob as almofadas e os pés na plataforma na largura dos ombros. Libere as travas e agache controladamente até os joelhos atingirem 90°. O tronco vertical da máquina elimina o trabalho da lombar, isolando o quadríceps. Pés mais baixos na plataforma = mais quadríceps; pés mais altos = mais glúteos e isquiotibiais.' },
        { id: 'agachamento_frontal', name: 'Agachamento Frontal', equipment: 'barra', difficulty: 'avancado', primaryMuscle: 'pernas', secondaryMuscles: ['core'], gif: 'exercises/1768273484428_Agachamento-Frontal-com-Barra-no-Banco.gif', description: 'Com a barra apoiada à frente nos ombros (pegada cruzada ou pronada com cotovelos elevados), mantenha o tronco o mais vertical possível durante a descida. Exige mobilidade significativa de tornozelos, quadris e ombros. O posicionamento anterior da barra recruta mais o quadríceps e o core. Desça até abaixo do paralelo se a mobilidade permitir e suba mantendo os cotovelos elevados.' },
        { id: 'agachamento_bulgaro', name: 'Agachamento Búlgaro', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos'], gif: 'exercises/1768273468610_Agachamento-Búlgaro-com-Halteres.gif', description: 'De pé com um pé apoiado num banco atrás do corpo, segure halteres nas mãos. Desça o joelho traseiro em direção ao chão enquanto o joelho dianteiro mantém alinhamento com o pé da frente. Desça até o joelho traseiro quase tocar o chão. Excelente para equilíbrio unilateral, correção de assimetrias e alto recrutamento de quadríceps e glúteos. Mais desafiador que o agachamento convencional.' },
        { id: 'agachamento_sumo', name: 'Agachamento Sumô', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos', 'adutores'], gif: 'exercises/1768273527713_Agachamento.gif', description: 'Com os pés afastados além da largura dos ombros e as pontas dos pés voltadas para fora entre 45–60°, segure a barra ou haltere. Agache mantendo os joelhos alinhados com a direção dos pés e o tronco relativamente ereto. A abertura ampla da passada ativa mais os adutores, glúteos e posteriores de coxa que o agachamento convencional. Descida até o paralelo ou abaixo.' },
        { id: 'leg_press', name: 'Leg Press', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos'], gif: 'exercises/1768273008898_LEG-PRESS-HORIZONTAL.gif', description: 'Deitado na máquina com as costas bem apoiadas, posicione os pés na plataforma na largura dos ombros. Libere as travas e desça a plataforma controladamente até os joelhos atingirem 90°. Empurre de volta sem travar os joelhos no topo. Pés mais altos = mais glúteos e isquiotibiais; pés mais baixos = mais quadríceps; pés mais afastados = mais adutores. Nunca eleve o quadril do assento.' },
        { id: 'leg_press_45', name: 'Leg Press 45°', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos'], gif: 'exercises/1768273008898_LEG-PRESS-HORIZONTAL.gif', description: 'Na versão inclinada a 45°, sente-se com as costas apoiadas no encosto e os pés na plataforma. Libere as travas laterais e desça a plataforma até os joelhos atingirem aproximadamente 90°. A inclinação permite carga maior e é confortável para as costas. Posicionamento dos pés mais alto na plataforma ativa mais glúteos; mais baixo ativa mais quadríceps. Não deixe os joelhos ultrapassarem demais os pés.' },
        { id: 'cadeira_extensora', name: 'Cadeira Extensora', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: [], gif: 'exercises/1768272995042_cadeira-extensora.gif', description: 'Sentado na máquina com os joelhos alinhados ao eixo de rotação e o tornozelo sob a almofada, estenda as pernas até a quase extensão completa. Contraia o quadríceps intensamente no ponto mais alto, segurando por 1–2 segundos. Desça controladamente. Exercício de isolamento puro para o quadríceps. Útil para reabilitação, para desenvolver a definição do quadríceps e como finalizador do treino.' },
        { id: 'mesa_flexora', name: 'Mesa Flexora', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: [], gif: 'exercises/1768273018500_mesa-flex.gif', description: 'Deitado de bruços na máquina com os tornozelos sob a almofada e os joelhos no final da mesa, flexione os joelhos levando o calcanhar em direção aos glúteos. Contraia os isquiotibiais no ponto final, segurando por 1 segundo. Retorne de forma controlada sem deixar o peso bater. Isolamento excelente para o grupo posterior da coxa, fundamental para prevenção de lesões e equilíbrio muscular.' },
        { id: 'cadeira_flexora', name: 'Cadeira Flexora', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: [], gif: 'exercises/1768272995810_cadeira-flex.gif', description: 'Sentado na máquina com os pés sob a almofada e os joelhos alinhados ao eixo de rotação, puxe as almofadas para baixo flexionando os joelhos. Contraia os isquiotibiais no ponto de maior flexão. A posição sentada oferece recrutamento diferente da mesa flexora, com maior ativação da porção distal dos isquiotibiais. Pode ser mais confortável para quem tem limitações na posição deitada.' },
        { id: 'stiff', name: 'Stiff', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos', 'lombar'], gif: 'exercises/1768273036998_stiff-com-barra.gif', description: 'De pé com a barra segura à frente do corpo, incline o tronco para frente mantendo as costas retas e as pernas levemente flexionadas. Desça a barra pela frente das pernas até sentir estiramento máximo nos isquiotibiais. Suba contraindo os isquiotibiais e os glúteos. Diferente do levantamento terra, as pernas ficam semi-estendidas durante todo o movimento, priorizando o estiramento e fortalecimento dos posteriores de coxa.' },
        { id: 'levantamento_terra_pernas', name: 'Levantamento Terra', equipment: 'barra', difficulty: 'avancado', primaryMuscle: 'pernas', secondaryMuscles: ['costas', 'glúteos'], gif: 'exercises/1768272761874_levantamento-terra-no-smith.gif', description: 'Com os pés na largura dos quadris e a barra sobre o meio dos pés, desça os quadris, eleve o peito e segure a barra com pegada pronada ou mista. Mantenha a barra rente às pernas durante toda a subida, empurrando o chão para baixo. Erga o quadril e os ombros na mesma velocidade. Exercício mais completo da musculação, ativando toda a cadeia posterior: isquiotibiais, glúteos, eretores e trapézio.' },
        { id: 'afundo', name: 'Afundo com Halteres', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos'], gif: 'exercises/1768273459859_Afundo-com-Halteres.gif', description: 'De pé com halteres nas mãos, dê um grande passo à frente. Desça o joelho traseiro em direção ao chão até o joelho dianteiro atingir 90°. Empurre com o calcanhar da perna da frente para voltar à posição inicial. Pode ser feito estático (alternando os pés) ou em caminhada. Trabalha quadríceps, glúteos e isquiotibiais unilateralmente, melhorando equilíbrio e corrigindo assimetrias.' },
        { id: 'adutora', name: 'Máquina Adutora', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: [], gif: 'exercises/1768273599214_Maquina-de-Adução-de-Quadril.gif', description: 'Sentado na máquina com as pernas abertas e apoiadas nas almofadas laterais, feche as pernas contra a resistência em movimento de adução de quadril. Contraia os adutores no ponto de maior fechamento das pernas. Retorne lentamente. Trabalha a face interna das coxas (adutores), músculos importantes para estabilidade do joelho e equilíbrio muscular. Use como complemento após os exercícios principais de pernas.' },
    ],

    gluteos: [
        { id: 'elevacao_pelvica', name: 'Elevação Pélvica com Barra', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'glúteos', secondaryMuscles: ['pernas'], gif: 'exercises/1768272935001_Elevacao-Pelvica-Com-Barra.gif', description: 'Sente-se no chão com as costas encostadas na lateral de um banco e a barra acolchoada sobre o quadril. Com os pés na largura dos ombros e joelhos flexionados, empurre o quadril para cima até alinhar ombros, quadril e joelhos. Contraia intensamente os glúteos no topo por 1–2 segundos. O hip thrust é o exercício mais eficaz cientificamente comprovado para ativação e hipertrofia do glúteo máximo.' },
        { id: 'elevacao_pelvica_maquina', name: 'Elevação Pélvica na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'glúteos', secondaryMuscles: [], gif: 'exercises/1768272937950_Elevacao-Pelvica-Na-Maquina.gif', description: 'Posicione-se na máquina de hip thrust com o quadril alinhado ao eixo de rotação e os ombros no apoio. Empurre o quadril para cima contraindo os glúteos no ponto mais alto. Retorne de forma controlada. A máquina oferece curva de resistência mais favorável para iniciantes e é mais segura que a versão com barra livre. Excelente para aprender o padrão motor da elevação pélvica.' },
        { id: 'gluteo_maquina', name: 'Glúteo na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'glúteos', secondaryMuscles: [], gif: 'exercises/1768272955410_Gluteo-Coice-Na-Máquina.gif', description: 'Em pé na máquina de extensão de quadril, posicione o tornozelo (ou a parte posterior da coxa) na almofada. Empurre a perna para trás em extensão do quadril, contraindo o glúteo máximo no ponto final. Mantenha o core contraído e mova apenas o quadril, evitando arqueamento excessivo da lombar. Retorne controladamente. Isolamento efetivo do glúteo máximo com resistência progressiva.' },
        { id: 'gluteo_polia', name: 'Glúteo na Polia', equipment: 'cabo', difficulty: 'intermediario', primaryMuscle: 'glúteos', secondaryMuscles: [], gif: 'exercises/1768272960642_Gluteos-na-Polia-Baixa.gif', description: 'Prenda a alça da polia baixa no tornozelo e fique de pé de frente para a máquina, apoiando as mãos para equilíbrio. Estenda o quadril para trás levando a perna para trás e para cima. Contraia o glúteo no ponto de extensão máxima. Retorne de forma controlada. O cabo mantém tensão constante durante todo o arco. Pode ser feito lateralmente para ativar o glúteo médio.' },
        { id: 'abdutora', name: 'Máquina Abdutora', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'glúteos', secondaryMuscles: [], gif: 'exercises/1768272962166_Maquina-de-Abducao-de-Quadril.gif', description: 'Sentado na máquina abdutora com os joelhos apoiados nas almofadas externas, abra as pernas para os lados contra a resistência. Contraia os glúteos médio e mínimo no ponto de abertura máxima. Retorne lentamente resistindo à fechamento. Fundamental para estabilidade lateral do quadril, prevenção de lesões no joelho e modelagem da parte lateral dos glúteos.' },
        { id: 'quatro_apoios', name: 'Quatro Apoios', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'glúteos', secondaryMuscles: [], gif: 'exercises/1768272334322_Alongamento-de-Quadriceps-em-Quatro-Apoios.gif', description: 'De quatro apoios com as mãos sob os ombros e os joelhos sob os quadris, eleve uma perna estendida ou flexionada para trás e para cima. Contraia o glúteo no ponto mais alto e retorne sem encostar o joelho no chão. Alterne as pernas. Exercício acessível e efetivo para iniciantes ativarem o glúteo máximo sem equipamento. Pode adicionar resistência com elástico ou caneleira.' },
        { id: 'ponte_haltere', name: 'Ponte com Haltere', equipment: 'halteres', difficulty: 'iniciante', primaryMuscle: 'glúteos', secondaryMuscles: [], gif: 'exercises/1768272964049_Ponte-com-Halteres.gif', description: 'Deitado de costas com os joelhos flexionados e os pés no chão na largura dos quadris, segure um halter sobre o quadril. Empurre o quadril para cima pressionando os calcanhares no chão, contraindo os glúteos no topo. Segure por 1–2 segundos e desça de forma controlada. Variante no solo do hip thrust, acessível para iniciantes e eficaz para ativação do glúteo máximo. Progrida aumentando a carga.' },
        { id: 'extensao_quadril_cabo', name: 'Extensão de Quadril com Cabo', equipment: 'cabo', difficulty: 'intermediario', primaryMuscle: 'glúteos', secondaryMuscles: [], gif: 'exercises/1768272947734_Extensao-de-Quadril-com-Cabo.gif', description: 'Com a alça da polia baixa presa ao tornozelo, fique de lado ou de frente à máquina com apoio para equilíbrio. Estenda o quadril levando a perna na direção de extensão máxima, contraindo o glúteo. O movimento unilateral isola cada glúteo individualmente, corrigindo desequilíbrios. A tensão constante do cabo ativa o glúteo de forma diferente das máquinas, com curva de resistência mais uniforme.' },
    ],

    abdomen: [
        { id: 'abdominal_supra', name: 'Abdominal Supra', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'abdômen', secondaryMuscles: [], gif: 'exercises/1768272256069_Abdominal-Supra-com-Alcance-(entre-as-pernas).-Variacao-onde-se-eleva-o-tronco-passando-os-bracos-esticados-no-meio-dos-joelhos..gif', description: 'Deitado com joelhos flexionados e pés no chão, coloque as mãos atrás da cabeça sem forçar o pescoço. Expire e eleve apenas os ombros do chão, contraindo o reto abdominal. Não levante a lombar completamente — o movimento deve ser curto e controlado. Segure 1 segundo no pico da contração e desça vagarosamente. Mantenha o queixo neutro olhando levemente para o teto.' },
        { id: 'abdominal_maquina', name: 'Abdominal na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'abdômen', secondaryMuscles: [], gif: 'exercises/1768272251926_ABDOMINAL-MAQUINA.gif', description: 'Sentado na máquina com as costas no encosto e as mãos nas alças acima da cabeça, flexione o tronco para baixo contra a resistência contraindo o abdômen. A máquina permite adição de carga progressiva, algo difícil com exercícios de peso corporal. Contraia intensamente no ponto de maior flexão e retorne de forma lenta e controlada. Excelente para desenvolvimento de abdômen com sobrecarga.' },
        { id: 'abdominal_polia', name: 'Abdominal na Polia', equipment: 'cabo', difficulty: 'intermediario', primaryMuscle: 'abdômen', secondaryMuscles: [], gif: 'exercises/1768272240456_Abdominal-Crunch-na-Polia-Alta-em-pe-Executado-no-cross-over.gif', description: 'Ajoelhado de frente à polia alta com a corda atrás da cabeça, flexione o tronco para baixo e para frente até os cotovelos se aproximarem dos joelhos. Mova apenas o tronco — não puxe com os braços nem mova os quadris. O cabo permite carga progressiva significativa e mantém tensão constante. Retorne vagarosamente. Um dos melhores exercícios para desenvolver o abdômen com sobrecarga real.' },
        { id: 'abdominal_infra', name: 'Abdominal Infra', equipment: 'corpo', difficulty: 'intermediario', primaryMuscle: 'abdômen', secondaryMuscles: [], gif: 'exercises/1768272248899_Abdominal-Infra-no-Solo-Elevacao-de-Pernas.gif', description: 'Deitado de costas com as mãos sob o glúteo para proteger a lombar, eleve as pernas estendidas até 90° em relação ao chão. Desça controladamente sem deixar os pés tocarem completamente o chão entre as repetições. Ativa principalmente o reto abdominal inferior e o iliopsoas. Para reduzir a dificuldade, flexione levemente os joelhos. Para aumentar, faça em superfície declinada.' },
        { id: 'abdominal_paralela', name: 'Abdominal na Paralela', equipment: 'corpo', difficulty: 'avancado', primaryMuscle: 'abdômen', secondaryMuscles: [], gif: 'exercises/1768272245558_Abdominal-Infra-na-Paralela.gif', description: 'Suspenso nas paralelas com os cotovelos apoiados e o corpo pendente, eleve os joelhos até a altura do peito ou as pernas estendidas até 90°. Contraia o abdômen e os flexores de quadril. Desça de forma controlada. Exercício avançado que combina força abdominal, de ombros e estabilidade total. Quanto mais estendidas as pernas, maior a dificuldade. Fundamental para força de core de alto nível.' },
        { id: 'prancha', name: 'Prancha', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'abdômen', secondaryMuscles: [], gif: 'exercises/1768272265712_PRANCHA.gif', description: 'Apoiado nos cotovelos e pontas dos pés, mantenha o corpo em linha reta da cabeça aos calcanhares. Contraia o abdômen, os glúteos e toda a cadeia posterior simultaneamente. Respire normalmente sem prender a respiração. Exercício isométrico fundamental para força de core profundo, que protege a lombar em todos os exercícios. Progrida aumentando o tempo ou adicionando variações como prancha lateral.' },
        { id: 'bicicleta', name: 'Abdominal Bicicleta', equipment: 'corpo', difficulty: 'intermediario', primaryMuscle: 'abdômen', secondaryMuscles: ['oblíquos'], gif: 'exercises/1768272236730_Abdominal-Bicicleta.gif', description: 'Deitado com as mãos leve atrás da cabeça e as pernas elevadas, leve o cotovelo direito em direção ao joelho esquerdo enquanto estende a perna direita. Alterne continuamente como se pedalasse. O movimento rotacional ativa simultaneamente o reto abdominal e os oblíquos. Um dos exercícios mais completos para o core, segundo pesquisas eletromiográficas. Mantenha o ritmo controlado e evite puxar o pescoço.' },
        { id: 'obliquo', name: 'Abdominal Oblíquo', equipment: 'corpo', difficulty: 'intermediario', primaryMuscle: 'abdômen', secondaryMuscles: [], gif: 'exercises/1768272253346_Abdominal-Obliquo-Cruzado-(unilateral).gif', description: 'Deitado, flexione um joelho e mantenha o pé no chão. Leve o ombro oposto em direção ao joelho flexionado em movimento de rotação do tronco. Mantenha os cotovelos abertos e o queixo neutro. O movimento rotacional ativa especificamente os oblíquos interno e externo, responsáveis pela definição lateral da cintura. Trabalhe ambos os lados igualmente para simetria.' },
        { id: 'abdominal_declinado', name: 'Abdominal Declinado', equipment: 'corpo', difficulty: 'intermediario', primaryMuscle: 'abdômen', secondaryMuscles: [], gif: 'exercises/1768272242128_Abdominal-Declinado-(feito-no-banco-inclinado)..gif', description: 'No banco declinado com os pés presos nos suportes, realize o abdominal completo com amplitude maior que no solo. Suba até os cotovelos quase alcançarem os joelhos e desça controladamente. O declive aumenta o ângulo de trabalho e intensifica o estímulo no reto abdominal comparado ao abdominal plano. Adicione um peso ao peito para progressão. Um dos mais eficazes para abdominal com sobrecarga.' },
    ],

    cardio: [
        { id: 'esteira', name: 'Esteira Ergométrica', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'cardio', secondaryMuscles: ['pernas'], gif: 'exercises/1768272712408_Corrida-na-Esteira.gif', description: 'Programe a velocidade e inclinação conforme o objetivo. Para queima de gordura, mantenha 60–70% da frequência cardíaca máxima por 30–45 minutos em ritmo moderado. Para condicionamento, intercale sprints de 20–30 segundos com recuperação de 1–2 minutos (HIIT). Mantenha a postura ereta, a passada natural e os braços balançando. Não apoie o peso nos corrimãos.' },
        { id: 'esteira_inclinada', name: 'Esteira Inclinada', equipment: 'maquina', difficulty: 'intermediario', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'glúteos'], gif: 'exercises/1768272713450_Corrida-na-Esteira-Inclinada.gif', description: 'Configure a inclinação entre 10–15% e caminhe em ritmo moderado. A inclinação aumenta significativamente a ativação de glúteos, posteriores de coxa e panturrilhas comparado à esteira plana. Oferece intensidade cardiovascular elevada com baixo impacto nas articulações. Sessões de 20–30 minutos são eficazes para queima calórica. Mantenha o tronco ereto sem apoiar nos corrimãos.' },
        { id: 'bicicleta_ergometrica', name: 'Bicicleta Ergométrica', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'cardio', secondaryMuscles: ['pernas'], gif: 'exercises/1768272716156_Airbike.gif', description: 'Ajuste o selim para que os joelhos fiquem levemente flexionados no ponto mais baixo do pedal. Pedale com cadência de 60–90 RPM para condicionamento aeróbico ou 90–120 RPM para trabalho anaeróbico. De baixíssimo impacto articular, é a escolha ideal para recuperação ativa, para quem tem limitações nos joelhos ou quer cardio longo sem desgaste. Sessões de 20–45 minutos são eficazes.' },
        { id: 'spinning', name: 'Spinning / Bicicleta Indoor', equipment: 'maquina', difficulty: 'intermediario', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'glúteos'], gif: 'exercises/1768272711604_Spinning-Bicicleta-Indoor.gif', description: 'Na bicicleta de spinning, ajuste o selim e o guidão para posição confortável. Alterne entre ritmo moderado, sprints e subidas simuladas com resistência elevada. O spinning combina cardio de alta intensidade com trabalho de quadríceps, glúteos e panturrilhas. Sessões geralmente duram 45–60 minutos. Queima entre 400–600 kcal por hora. Excelente para condicionamento cardiovascular sem impacto articular.' },
        { id: 'eliptico', name: 'Elíptico', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'braços'], gif: 'exercises/1768272734532_Máquina-Eliptica.gif', description: 'O elíptico combina o padrão de movimento de corrida com o de esqui nórdico, trabalhando membros inferiores e superiores simultaneamente. Sem impacto no solo, é ideal para cardio de baixo impacto. Use os braços ativamente empurrando e puxando para maximizar o gasto calórico e o trabalho de membros superiores. Mantenha o tronco ereto e a resistência suficiente para sentir o esforço.' },
        { id: 'eliptico_horizontal', name: 'Elíptico Horizontal', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'glúteos'], gif: 'exercises/1768272709754_Eliptico-Horizontal.gif', description: 'O elíptico horizontal (stairstepper ou crosstrainer horizontal) simula o padrão de subir escadas em amplitude longa. Ativa glúteos, quadríceps e isquiotibiais de forma intensa com zero impacto articular. Segure as alças laterais para equilíbrio e mantenha o tronco ereto durante todo o movimento. Ideal para pessoas com limitações de joelho ou quadril que desejam treino cardiovascular seguro e eficaz.' },
        { id: 'simulador_escada', name: 'Simulador de Escada', equipment: 'maquina', difficulty: 'intermediario', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'glúteos'], gif: 'exercises/1768272715235_Simulador-de-Escada-Stairmaster.gif', description: 'Posicione-se na máquina Stairmaster e inicie subindo degraus em ritmo constante. Mantenha o tronco ereto sem apoiar todo o peso nos corrimãos. Ativa intensamente quadríceps, glúteos, isquiotibiais e panturrilhas. Sessões de 15–30 minutos são muito desafiadoras. Para intensificar, suba dois degraus de uma vez para maior ativação de glúteos. Excelente para modelagem do corpo e condicionamento cardiovascular.' },
        { id: 'subida_escada_maquina', name: 'Subida de Escada na Máquina', equipment: 'maquina', difficulty: 'intermediario', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'glúteos'], gif: 'exercises/1768272702642_Subida-de-Escada-Maquina.gif', description: 'Na máquina de escada com corrimãos laterais, suba os degraus em ritmo constante sem apoiar o peso nos corrimãos. O movimento de subida recruta fortemente os glúteos, quadríceps e panturrilhas. É uma das máquinas com maior gasto calórico relativo. Comece com sessões de 10–15 minutos e progrida gradualmente. O esforço cardiovascular é elevado, tornando-a excelente para quem quer emagrecer e tonificar.' },
        { id: 'airbike', name: 'Air Bike', equipment: 'maquina', difficulty: 'avancado', primaryMuscle: 'cardio', secondaryMuscles: ['corpo todo'], gif: 'exercises/1768272716156_Airbike.gif', description: 'A air bike usa resistência de ar proporcional à intensidade da pedalada, tornando-a extremamente desafiadora em qualquer nível. Use braços e pernas simultaneamente para maximizar o gasto calórico e o recrutamento muscular total. Para HIIT: sprints máximos de 10–20 segundos com descanso de 40–60 segundos por 8–10 rounds. Uma das ferramentas mais eficazes para condicionamento cardiovascular e queima de gordura.' },
        { id: 'pular_corda', name: 'Pular Corda', equipment: 'corpo', difficulty: 'intermediario', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'ombros'], gif: 'exercises/1768272710808_Pular-Corda.gif', description: 'Segure as alças da corda ao lado do corpo, gire os pulsos (não os ombros) para girar a corda e salte com os dois pés juntos ou alternados. Aterrisse suavemente na ponta dos pés, mantendo os joelhos levemente flexionados. Uma das ferramentas mais eficientes para cardio: queima até 10–15 kcal por minuto. Desenvolve coordenação, ritmo, força de panturrilha e condicionamento cardiovascular. Progressão: cross jump, double under.' },
        { id: 'corrida_ar_livre', name: 'Corrida ao Ar Livre', equipment: 'corpo', difficulty: 'intermediario', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'glúteos'], gif: 'exercises/1768272708319_Corrida-ao-Ar-Livre-Sprint.gif', description: 'Corra ao ar livre mantendo postura ereta, olhar no horizonte e os braços dobrados a 90° balançando naturalmente. Para corrida contínua (Zone 2), mantenha ritmo em que consiga falar frases curtas. Para intervalado, alterne sprints de 30–60 segundos com trote de recuperação de 1–2 minutos. O solo irregular e o vento oferecem estímulo adicional comparado à esteira. Ideal para condicionamento aeróbico e mental.' },
        { id: 'ciclismo_ar_livre', name: 'Ciclismo ao Ar Livre', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'glúteos'], gif: 'exercises/1768272706995_Ciclismo-ao-Ar-Livre.gif', description: 'Pedale ao ar livre mantendo cadência de 70–90 RPM em terreno plano. Em subidas, reduza a marcha e aumente o esforço muscular das pernas. Em descidas, recupere. O ciclismo ao ar livre trabalha quadríceps, glúteos, isquiotibiais e panturrilhas com baixo impacto. É uma das formas mais agradáveis de cardio, permitindo longas sessões sem monotonia. Hidrate-se adequadamente em treinos acima de 45 minutos.' },
        { id: 'polichinelo', name: 'Polichinelo', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'ombros'], gif: 'exercises/1768272703412_Polichinelo.gif', description: 'Em pé com os pés juntos e os braços ao lado do corpo, salte abrindo os pés além da largura dos ombros enquanto eleva os braços acima da cabeça. Retorne saltando de volta à posição inicial. Mantenha ritmo constante e aterrisse suavemente. Excelente exercício de aquecimento e cardio sem equipamento que ativa todo o corpo. Séries de 30–60 segundos são eficazes. Pode ser feito em qualquer lugar sem necessidade de espaço ou equipamento.' },
        { id: 'agachamento_salto', name: 'Agachamento com Salto', equipment: 'corpo', difficulty: 'intermediario', primaryMuscle: 'cardio', secondaryMuscles: ['pernas', 'glúteos'], gif: 'exercises/1768272705148_Agachamento-com-Salto.gif', description: 'Realize um agachamento completo e, ao subir, exploda verticalmente saltando o mais alto possível com os braços impulsionando para cima. Aterrisso amortecendo com as pontas dos pés primeiro e os joelhos levemente flexionados, transitando direto para o próximo agachamento. Combina força explosiva, potência e cardio de alta intensidade. Desenvolve quadríceps, glúteos e capacidade anaeróbica. Execute 3–5 séries de 8–15 repetições.' },
        { id: 'battle_rope', name: 'Battle Rope', equipment: 'corpo', difficulty: 'avancado', primaryMuscle: 'cardio', secondaryMuscles: ['ombros', 'costas', 'core'], gif: 'exercises/1768272706222_Battle-Rope-Corda-de-Batalha.gif', description: 'Segure uma ponta da corda em cada mão, afaste os pés na largura dos ombros e flexione levemente os joelhos. Faça ondas alternadas (uma mão sobe enquanto a outra desce) ou simultâneas com máxima potência. Mantenha o core contraído e as costas retas durante todo o exercício. As battle ropes combinam cardio de alta intensidade com fortalecimento de ombros, dorsais, core e braços. Trabalhe em intervalos de 20–40 segundos com descanso equivalente.' },
    ],

    trapezio: [
        { id: 'encolhimento_barra', name: 'Encolhimento com Barra', equipment: 'barra', difficulty: 'iniciante', primaryMuscle: 'trapézio', secondaryMuscles: ['ombros'], gif: 'exercises/1768272700951_Afundo-Caminhando.gif', description: 'Em pé com a barra segura à frente do corpo com pegada pronada na largura dos ombros, eleve os ombros diretamente para cima o máximo possível, como se tentasse tocar as orelhas. Segure por 1–2 segundos no pico da contração e desça lentamente. Não gire os ombros — o movimento é puramente vertical. O trapézio superior é o principal motor, mas o levantador da escápula e o rombóide também são ativados.' },
        { id: 'encolhimento_halteres', name: 'Encolhimento com Halteres', equipment: 'halteres', difficulty: 'iniciante', primaryMuscle: 'trapézio', secondaryMuscles: ['ombros'], gif: 'exercises/1768272700951_Afundo-Caminhando.gif', description: 'Em pé com um halter em cada mão ao lado do corpo, eleve os ombros verticalmente o máximo possível sem girar ou circular. Contraia o trapézio superior no topo por 1–2 segundos. Os halteres permitem maior amplitude de movimento e posição natural dos braços ao longo do corpo. Ideal para quem sente desconforto no pulso com a barra. Evite balanços com o tronco para auxiliar o movimento.' },
        { id: 'remada_alta_trap', name: 'Remada Alta para Trapézio', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'trapézio', secondaryMuscles: ['ombros'], gif: 'exercises/1768272700951_Afundo-Caminhando.gif', description: 'Com a barra segura com pegada pronada estreita (20–30 cm), puxe verticalmente até o queixo conduzindo os cotovelos para fora e para cima. O trapézio superior e o deltoides médio são os motores principais. Contraia no ponto mais alto e desça de forma controlada. Evite pegada muito fechada que pode causar impingimento subacromial. Alternativa: use halter ou cabo para variação unilateral.' },
        { id: 'face_pull', name: 'Face Pull', equipment: 'cabo', difficulty: 'iniciante', primaryMuscle: 'trapézio', secondaryMuscles: ['ombros', 'romboides'], gif: 'exercises/1768272700951_Afundo-Caminhando.gif', description: 'Com a corda na polia alta na altura dos olhos, recue um passo e segure as pontas da corda com os cotovelos a 90°. Puxe a corda em direção ao rosto, separando as mãos e abrindo os cotovelos para os lados até os braços formarem um "W". Contraia o trapézio médio e o deltoides posterior. Fundamental para saúde dos ombros e postura. Retorne controladamente. Execute com leve inclinação do tronco para trás.' },
    ],

    antebraco: [
        { id: 'rosca_punho_supinada', name: 'Rosca de Punho Supinada', equipment: 'barra', difficulty: 'iniciante', primaryMuscle: 'antebraço', secondaryMuscles: [], gif: 'exercises/1768272636144_Rosca-Direta-com-Barra-deitado-em-Banco-Alto.gif', description: 'Sentado com os antebraços apoiados nas coxas e as palmas voltadas para cima, segure a barra e flexione os punhos para cima o máximo possível. Contraia os flexores do antebraço no pico e desça controladamente. Movimento de pequena amplitude mas altamente efetivo para desenvolver os flexores do carpo e os músculos do antebraço anterior. Essencial para força de pegada e estética do braço.' },
        { id: 'rosca_punho_pronada', name: 'Rosca de Punho Pronada', equipment: 'barra', difficulty: 'iniciante', primaryMuscle: 'antebraço', secondaryMuscles: [], gif: 'exercises/1768272657628_Rosca-martelo-com-corda.gif', description: 'Sentado com os antebraços apoiados nas coxas e as palmas voltadas para baixo (pronadas), segure a barra e eleve os punhos para cima. Trabalha os extensores do carpo no dorso do antebraço. Movimento inverso da rosca supinada, essencial para equilíbrio muscular e prevenção de lesões como epicondilite. A amplitude é menor que na versão supinada. Execute com peso leve e controle total.' },
        { id: 'rosca_martelo_antebraco', name: 'Rosca Martelo', equipment: 'halteres', difficulty: 'iniciante', primaryMuscle: 'antebraço', secondaryMuscles: ['bíceps'], gif: 'exercises/1768272657628_Rosca-martelo-com-corda.gif', description: 'Em pé com os halteres em pegada neutra (palmas voltadas para o corpo), flexione os braços sem girar os punhos. O braquiorradial, principal músculo do antebraço lateral, é o motor principal junto com o braquial anterior. Desenvolve a espessura e o relevo do antebraço. Pode ser feito alternado para foco unilateral ou com corda na polia para resistência constante ao longo de todo o arco.' },
        { id: 'farmer_walk', name: 'Farmer Walk', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'antebraço', secondaryMuscles: ['trapézio', 'core'], gif: 'exercises/1768272657628_Rosca-martelo-com-corda.gif', description: 'Pegue halteres pesados (ou kettlebells) em cada mão e caminhe por uma distância predeterminada (20–40 metros) mantendo o tronco ereto, os ombros retraídos e o core firme. Um dos exercícios mais funcionais e efetivos para força de pegada e resistência do antebraço. Também desenvolve intensamente o trapézio, os estabilizadores do core e a musculatura postural. Aumente o peso progressivamente.' },
    ],

    alongamentos: [
        { id: 'alongamento_quadriceps', name: 'Alongamento de Quadríceps', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: [], gif: 'exercises/1768272334322_Alongamento-de-Quadriceps-em-Quatro-Apoios.gif', description: 'Em pé sobre uma perna, dobre o joelho da outra perna e segure o tornozelo com a mão correspondente. Mantenha os joelhos alinhados e o tronco ereto. Sinta o alongamento na face anterior da coxa. Segure por 20–30 segundos e alterne os lados. Fundamental para manter flexibilidade do quadríceps e da articulação do joelho, especialmente após treinos de pernas ou corridas longas.' },
        { id: 'alongamento_isquiotibiais', name: 'Alongamento de Isquiotibiais', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: ['lombar'], gif: 'exercises/1768272334322_Alongamento-de-Quadriceps-em-Quatro-Apoios.gif', description: 'Sentado no chão com uma perna estendida e a outra flexionada (sola do pé junto à coxa), incline o tronco para frente sobre a perna estendida mantendo as costas retas. Alcance o pé ou o tornozelo sem arredondar a lombar. Sinta o alongamento na parte posterior da coxa. Segure 20–30 segundos. Essencial para flexibilidade dos posteriores, prevenção de lesões e melhora da postura.' },
        { id: 'alongamento_gluteo', name: 'Alongamento de Glúteo', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'glúteos', secondaryMuscles: [], gif: 'exercises/1768272334322_Alongamento-de-Quadriceps-em-Quatro-Apoios.gif', description: 'Deitado de costas, cruze uma perna sobre o joelho da outra formando o número 4. Puxe suavemente a coxa da perna de baixo em direção ao peito até sentir o alongamento profundo no glúteo da perna cruzada (piriforme). Segure 20–30 segundos e alterne. Fundamental para liberar tensão no glúteo e no piriforme, aliviando ciática e dores lombares. Execute na expiração para relaxar mais profundamente.' },
        { id: 'alongamento_peitoral', name: 'Alongamento de Peitoral', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'peitoral', secondaryMuscles: ['ombros'], gif: 'exercises/1768272334322_Alongamento-de-Quadriceps-em-Quatro-Apoios.gif', description: 'De pé próximo a uma parede ou coluna, posicione o antebraço verticalmente na superfície com o cotovelo a 90°. Gire suavemente o tronco para o lado oposto até sentir o alongamento no peitoral e deltoides anterior. Segure 20–30 segundos e alterne os lados. Combate a retração postural causada por treinos intensos de peito e trabalho em frente ao computador. Também pode ser feito com os braços esticados.' },
        { id: 'alongamento_dorsal', name: 'Alongamento de Grande Dorsal', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'costas', secondaryMuscles: [], gif: 'exercises/1768272334322_Alongamento-de-Quadriceps-em-Quatro-Apoios.gif', description: 'Pendurado na barra fixa com os braços completamente estendidos, relaxe os ombros e deixe o peso do corpo alongar o grande dorsal. Segure por 20–30 segundos. Alternativamente, ajoelhe-se à frente de um banco, apoie as mãos nele e recline os quadris para trás para sentir o estiramento lateral. Excelente para aliviar a tensão nas costas após treinos de puxada e para melhorar a mobilidade de ombros.' },
    ],

    eretores: [
        { id: 'hiperextensao', name: 'Hiperextensão', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'eretores', secondaryMuscles: ['glúteos', 'isquiotibiais'], gif: 'exercises/1768272761874_levantamento-terra-no-smith.gif', description: 'No banco de hiperextensão (romano), posicione os quadris sobre a almofada e os calcanhares sob os suportes. Com as mãos atrás da cabeça ou cruzadas no peito, desça o tronco controladamente até sentir leve estiramento nos eretores. Suba contraindo a lombar e os glúteos até o corpo ficar paralelo ao chão. Evite hiperextender além do paralelo. Fundamental para fortalecer a cadeia posterior e proteger a lombar.' },
        { id: 'hiperextensao_invertida', name: 'Hiperextensão Invertida', equipment: 'maquina', difficulty: 'intermediario', primaryMuscle: 'eretores', secondaryMuscles: ['glúteos'], gif: 'exercises/1768272761874_levantamento-terra-no-smith.gif', description: 'Deitado de bruços na máquina de hiperextensão invertida com os quadris na borda, segure as alças e balance as pernas para cima em extensão do quadril e da lombar. Os eretores e o glúteo máximo trabalham juntos para elevar as pernas. Retorne controladamente sem deixar bater. Excelente para descompressão vertebral e fortalecimento da lombar com menor carga axial comparado ao levantamento terra.' },
        { id: 'good_morning', name: 'Good Morning', equipment: 'barra', difficulty: 'intermediario', primaryMuscle: 'eretores', secondaryMuscles: ['glúteos', 'isquiotibiais'], gif: 'exercises/1768272761874_levantamento-terra-no-smith.gif', description: 'Com a barra apoiada nos trapézios como no agachamento, afaste os pés na largura dos ombros e mantenha joelhos levemente flexionados. Incline o tronco para frente mantendo as costas retas e a lombar neutra até o tronco ficar próximo ao paralelo. Contraia os eretores e os glúteos para voltar à posição vertical. Desenvolve força específica dos eretores na posição de maior vulnerabilidade, melhorando a segurança no terra e no agachamento.' },
        { id: 'superman', name: 'Superman', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'eretores', secondaryMuscles: ['glúteos'], gif: 'exercises/1768272761874_levantamento-terra-no-smith.gif', description: 'Deitado de bruços com os braços estendidos à frente, eleve simultaneamente os braços, o peito e as pernas do chão, contraindo os eretores e os glúteos. Segure 2–3 segundos no ponto mais alto e desça. Exercício de peso corporal acessível para ativar e fortalecer toda a cadeia posterior: eretores, glúteos e isquiotibiais. Ideal para aquecimento, reabilitação lombar e iniciantes que ainda não realizam levantamentos com carga.' },
    ],

    membros_inf: [
        { id: 'afundo_caminhando', name: 'Afundo Caminhando', equipment: 'halteres', difficulty: 'intermediario', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos'], gif: 'exercises/1768273459859_Afundo-com-Halteres.gif', description: 'Com halteres nas mãos, dê um passo largo à frente e desça o joelho traseiro quase até o chão com o joelho dianteiro a 90°. Em vez de voltar ao ponto inicial, empurre para frente dando o próximo passo com a outra perna, avançando progressivamente. Desenvolve coordenação, equilíbrio e força unilateral das pernas e glúteos. Mais desafiador que o afundo estático por exigir controle dinâmico do movimento.' },
        { id: 'step_up', name: 'Step Up', equipment: 'halteres', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos'], gif: 'exercises/1768273459859_Afundo-com-Halteres.gif', description: 'De pé na frente de um banco ou step, suba com um pé sobre a plataforma e empurre com o calcanhar para elevar o corpo. Suba com a outra perna e desça de forma controlada. O height do step determina a dificuldade: mais alto = maior ativação de glúteos; mais baixo = mais quadríceps. Exercício funcional que simula subir escadas. Pode ser feito com halteres para progressão.' },
        { id: 'passada_lateral', name: 'Passada Lateral', equipment: 'corpo', difficulty: 'iniciante', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos', 'adutores'], gif: 'exercises/1768273468610_Agachamento-Búlgaro-com-Halteres.gif', description: 'De pé com os pés juntos, dê um passo largo para o lado e desça o quadril em direção ao calcanhar da perna que passou, mantendo a outra perna estendida. Empurre com o calcanhar para retornar e repita no outro lado. Ativa adutores, abdutores, quadríceps e glúteo médio em padrão de movimento frontal, que muitas vezes é negligenciado em treinos. Melhora estabilidade lateral do joelho.' },
        { id: 'agachamento_sumatra', name: 'Agachamento com Salto', equipment: 'corpo', difficulty: 'intermediario', primaryMuscle: 'pernas', secondaryMuscles: ['glúteos'], gif: 'exercises/1768273527713_Agachamento.gif', description: 'Realize um agachamento completo e, ao subir, exploda verticalmente saltando o mais alto possível. Aterrisso amortecendo com as pontas dos pés primeiro e os joelhos levemente flexionados. Combina força, potência e condicionamento cardiovascular. Desenvolve a capacidade explosiva do quadríceps e glúteos. Executa em séries de 8–15 repetições com foco na altura do salto e na qualidade do amortecimento.' },
    ],

    panturrilhas: [
        { id: 'panturrilha_maquina', name: 'Panturrilha na Máquina', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'panturrilhas', secondaryMuscles: [], gif: 'exercises/1768272995042_cadeira-extensora.gif', description: 'Sentado na máquina de panturrilha com os joelhos a 90° e o suporte posicionado sobre as coxas, eleve os calcanhares o máximo possível para cima. Segure 1–2 segundos no pico da contração e desça até sentir o estiramento máximo do gastrocnêmio e sóleo. A posição sentada enfatiza o sóleo (músculo profundo da panturrilha) mais que os exercícios em pé. Alto volume de repetições é geralmente mais efetivo.' },
        { id: 'panturrilha_em_pe', name: 'Panturrilha em Pé', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'panturrilhas', secondaryMuscles: [], gif: 'exercises/1768272995042_cadeira-extensora.gif', description: 'Na máquina de panturrilha em pé com os ombros sob as almofadas e a ponta dos pés na plataforma, eleve os calcanhares o máximo possível contraindo o gastrocnêmio (músculo mais superficial e volumoso da panturrilha). Segure 1–2 segundos e desça completamente para máximo estiramento. A posição em pé com joelhos estendidos ativa primariamente o gastrocnêmio, dando volume e definição à panturrilha.' },
        { id: 'panturrilha_unilateral', name: 'Panturrilha Unilateral', equipment: 'corpo', difficulty: 'intermediario', primaryMuscle: 'panturrilhas', secondaryMuscles: [], gif: 'exercises/1768272995042_cadeira-extensora.gif', description: 'Apoie a ponta de um pé no degrau de uma escada ou step com o calcanhar livre no ar. Segure algo para equilíbrio e suba na ponta do pé o máximo possível, contraindo intensamente o gastrocnêmio. Desça além do nível do degrau para estiramento máximo. Unilateral, permite corrigir desequilíbrios entre as panturrilhas e a carga do peso corporal é suficiente para estimular o músculo. Progrida segurando um halter.' },
        { id: 'panturrilha_leg_press', name: 'Panturrilha no Leg Press', equipment: 'maquina', difficulty: 'iniciante', primaryMuscle: 'panturrilhas', secondaryMuscles: [], gif: 'exercises/1768272995042_cadeira-extensora.gif', description: 'No leg press, posicione apenas a ponta dos pés na borda inferior da plataforma com os joelhos levemente flexionados. Empurre a plataforma com as pontas dos pés elevando os calcanhares (plantiflexão). Segure 1–2 segundos e desça controladamente. A posição no leg press permite carga muito maior que os exercícios em pé, sendo eficiente para sobrecarga progressiva das panturrilhas. Ótimo complemento para o treino de pernas.' },
    ],
};

// URL Base opcional se algum dia precisarmos
const LOCAL_GIF_BASE = '/gifs/';

// Função para obter URL do GIF
export const getExerciseGifUrl = (gifPath) => {
    if (!gifPath) return null;

    // Usa a env var ou um fallback hardcodeado por segurança
    const publicDomain = import.meta.env.VITE_R2_PUBLIC_DOMAIN || 'https://pub-4f9f26919fd14ab99c0e0208f073927d.r2.dev';

    const pathStr = String(gifPath);
    if (pathStr.toLowerCase().startsWith('http')) {
        return pathStr;
    }

    // Remove barra inicial se houver para evitar duplicidade na junção
    const cleanPath = gifPath.startsWith('/') ? gifPath.slice(1) : gifPath;

    // Codifica cada segmento do caminho para lidar com espaços e acentos corretamente
    // Ex: "Peitoral/supindo reto.gif" -> "Peitoral/supindo%20reto.gif"
    const encodedPath = cleanPath.split('/').map(segment => encodeURIComponent(decodeURIComponent(segment))).join('/');

    return `${publicDomain}/${encodedPath}`.replace(/([^:]\/)\/+/g, "$1");
};

// Função para obter total de exercícios
export const getTotalExercises = () => {
    return Object.values(exerciseDatabase).reduce((total, group) => total + group.length, 0);
};

// Exportar todos os exercícios em lista única
export const getAllExercises = () => {
    const all = [];
    Object.entries(exerciseDatabase).forEach(([groupId, exercises]) => {
        exercises.forEach(ex => {
            all.push({ ...ex, groupId });
        });
    });
    return all;
};
